INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ice Age: Scrat''s Nutty Adventure', 'In Ice Age: Scrat’s Nutty Adventure, Scrat, the calamitous sabre-toothed squirrel, will embark on an epic quest through classic Ice Age locations to recover his cherished acorn from the ancient Scratazon Temple. Only the legendary Crystal Nuts can unlock his prized possession, which Scrat will attempt to collect as he faces fierce prehistoric creatures, to return the missing relics to their rightful home. Players will guide Scrat through a perilous journey across icy terrains,raging geysers, and burning lava. Explore adventure-packed locations to discover treasures that unlock special powers and help Scrat to jump higher, grab heavier objects and find every last treasure in this all new Nutty adventure!' FROM games WHERE igdb_id = 119930 ON CONFLICT (game_id, language_code) DO NOTHING;
