INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-wanderer-frankensteins-creature', 122049, '2019-10-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8yoe.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar73h.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Wanderer: Frankenstein''s Creature', 'In this exploration/adventure game, you play Frankenstein''s Creature, a being with no memory and past. At the start of the game you know neither Good nor Evil, you are a blank soul in an adult body. By exploring the world, you will experience your emotions, develop and write the first pages of your story. When confronted with mankind, there will be no way to escape the question of your origins: Who abandoned you in this world? Hunted by this question The Wanderer: Frankenstein''s Creature will take you on an adventure throughout Europe. Your experiences - some brutal and tragic, others joyful - as well as your choices, will bring you closer to the truth with every step. But will you be ready to face this truth?' FROM games WHERE igdb_id = 122049 ON CONFLICT (game_id, language_code) DO NOTHING;
