INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Showdown Bandit', 'Something unnatural is stirring on the abandoned sets of the once popular kids puppet show, Showdown Bandit. Play as the awakened Bandit in this stealth-action-horror where your only hope of survival is entangled within the 3 rules of the show: Play your part. Guard your strings. And don’t look up!' FROM games WHERE igdb_id = 121497 ON CONFLICT (game_id, language_code) DO NOTHING;
