INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Just Cause 4: Reloaded', 'Just Cause 4 Reloaded delivers an expansive and explosive gameplay experience in an all-new package! Just Cause 4 Reloaded includes additional premium content as well as all previously released improvements and additions to the game. Jump into an action-packed open-world sandbox experience and cause chaos with a wide selection of weaponry, vehicles and gear. Strap into your wingsuit, equip your fully customizable grappling hook, and get ready to bring the thunder!
