INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Apple Knight', 'Apple Knight is a modern action platformer with tight controls, fluid player movement, and smooth animation. Explore vast levels filled with secrets, quests and loot. Defeat tough bosses. Fight your way through hordes of evil wizards, knights, and creatures - or activate traps to take them out from a safe distance!' FROM games WHERE igdb_id = 127033 ON CONFLICT (game_id, language_code) DO NOTHING;
