INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Little Big Workshop', 'Imagine a magical factory, appearing right in your living room. A carefully planned masterpiece, where diligent workers throw together anything customers want. Rubber ducks and dressers, drones and electric guitars, scooters and other wonderful goods can be created from many different materials and sold for hard cash – cash you invest right back into your factory to get more machines, more workers and grow your business. In Little Big Workshop you become a factory tycoon!' FROM games WHERE igdb_id = 124131 ON CONFLICT (game_id, language_code) DO NOTHING;
