INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gem Collector', 'Gem Collector is a puzzle/arcade game. Collect all gems spread around level. Watch out for falling stones. Defeat enemies using power stone pushes or TNT. For those who are creative there is an intuitive Level Editor. Once you design a level share it with others using one-click Level Publisher.' FROM games WHERE igdb_id = 121249 ON CONFLICT (game_id, language_code) DO NOTHING;
