INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sakura Wars', 'The Imperial Combat Revue takes the stage as Tokyo’s defense force against a demon threat in this extravagant adventure. Soldiers in wartime, but theater performers in peacetime, the Revue’s Flower Division is not living up to their legacy and is at risk of being shut down. As newly appointed captain Seijuro Kamiyama, it’s up to you to turn the team around.' FROM games WHERE igdb_id = 96392 ON CONFLICT (game_id, language_code) DO NOTHING;
