INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('late-night-1320', 115654, '2019-03-16', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobst6.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc67ps.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Late Night 1320', 'Experience a blast to the past of old school drag racing in its purest form. Find a variety of classic cars, trucks, and odd vehicles from the junkyard and rescue them from their inevitable demise. Once you''ve restored and fixed your junker, take it to the backroads and compete against a variety of racers to earn their respect. Work your way up the chain and gain rep with the local crowd. Discover new drag spots to further work your way up the chain and continue upgrading your car. Compete at the drag strip for the ultimate test against sponsored racers and become the Late Night king.' FROM games WHERE igdb_id = 115654 ON CONFLICT (game_id, language_code) DO NOTHING;
