INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Oceanhorn 2: Knights of the Lost Realm', 'Oceanhorn 2: Knights of the Lost Realm, set a thousand years before the events of the first chapter, takes the player on a magical journey across the vast world of Gaia, brimming with mythology and lore. A young Knight faces an impossible challenge, as Warlock Mesmeroth has returned with a formidable Dark Army. Will the hero be able to unite the Owrus, Gillfolk, and men in a fight for the fate of the world?' FROM games WHERE igdb_id = 22800 ON CONFLICT (game_id, language_code) DO NOTHING;
