INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('cadence-of-hyrule-crypt-of-the-necrodancer-featuring-the-legend-of-zelda', 116419, '2019-06-13', 82, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1qgt.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar58u.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cadence of Hyrule: Crypt of the NecroDancer Featuring the Legend of Zelda', 'Cadence of Hyrule: Crypt of the NecroDancer Featuring The Legend of Zelda is a rhythmic action-adventure game where you can enjoy the gameplay of Crypt of the NecroDancer in the setting of The Legend of Zelda series. As Link - or even as Princess Zelda - you''ll explore the randomly generated overworld and procedurally generated dungeons on a quest to save Hyrule. Every beat of each remixed Legend of Zelda tune is a chance to move, attack, defend, and more, so stay one step ahead of each enemy and boss… or face the music.' FROM games WHERE igdb_id = 116419 ON CONFLICT (game_id, language_code) DO NOTHING;
