INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Trover Saves the Universe', 'Wonderful. Your dogs have been dognapped by a beaked lunatic who stuffed them into his eye holes and is using their life essence to destroy the universe. Does that make any sense? You''ve partnered with Trover, a little purple eye hole monster to save them. Find power babies and plug them into his eye holes so that he can absorb their power, track down Glorkon, and save your dogs (and the Universe).' FROM games WHERE igdb_id = 103331 ON CONFLICT (game_id, language_code) DO NOTHING;
