INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Grand Tour Game', 'Ever wish you could get behind the wheel with Clarkson, Hammond, and May from The Grand Tour? Now it''s your turn! One moment you''re watching the hosts attempt some questionable automotive antics... the next you''re at the wheel yourself - same car, same location, same chance to make a massive mess of it.' FROM games WHERE igdb_id = 107227 ON CONFLICT (game_id, language_code) DO NOTHING;
