INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NekoMiko', 'The main character is an unfortunate man who can''t do anything well. One fateful day, he meets 2 cat-eared shrine maidens by the name of Ayame and Kaede at an old shrine, and ends up living with them! Set in Akihabara, enjoy this adventure game of the slightly dirty-minded and eventful cohabitation life with 2 cat-eared shrine maidens.' FROM games WHERE igdb_id = 114367 ON CONFLICT (game_id, language_code) DO NOTHING;
