INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rise of the Teenage Mutant Ninja Turtles: Epic Mutant Missions', 'Splinter''s special items are missing! Help Raph, Donnie, Leo, and Mikey find the missing items and fight off the bad guys. In Nickelodeon''s newest free and fun online action game, it''s up to you to guide the turtles through different quests and challenges. Each mission allows you to earn trophies, find the missing items and explore different locations in Manhattan.' FROM games WHERE igdb_id = 146290 ON CONFLICT (game_id, language_code) DO NOTHING;
