INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Atelier Lulua: The Scion of Arland', 'The 4th entry in the Atelier "Arland" series, released 10 years after Atelier Rorona''s launch date. Learn about the world of Arland in Lulua’s perspective as she deciphers the mysterious “Alchemyriddle” book with no time pressure. New and old fans can enjoy the new Synthesis system that features "Dual Elemental Attributes" and "Awakened Effects", as well as a Turn-based Battle system inspired by Atelier Lydie & Suelle while introducing combat features such as “Interrupts” and “Primal Arts”.' FROM games WHERE igdb_id = 111330 ON CONFLICT (game_id, language_code) DO NOTHING;
