INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('witcheye', 121440, '2019-08-15', 73, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1vjt.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar61q.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Witcheye', 'Witcheye is a big, colorful, old-school platform adventure with a unique touchscreen control system that gives unparalleled control over the hero. Swipe to move and touch to stop, bouncing off of enemies and dodging hazards in six vibrant worlds. Set off on an adventure as a mild-mannered witch who transforms into a flying eyeball of vengeance after a smarmy knight and wizard steal her spell ingredients. You''ll guide her through 50+ levels, each containing something completely unique: tricky new enemies, mysterious new environments, and puzzling new secrets. These elements are brought to life with colorful, clean pixel art and a lively, head-bobbing original soundtrack.' FROM games WHERE igdb_id = 121440 ON CONFLICT (game_id, language_code) DO NOTHING;
