INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Trailmakers', 'In the toughest motoring expedition in the universe, you and your friends will build your own vehicles to cross a dangerous wasteland. Explore, crash horribly, use your wits to build a better rig, and get as far as you can with whatever spare parts you find on your way.' FROM games WHERE igdb_id = 29667 ON CONFLICT (game_id, language_code) DO NOTHING;
