INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Mario Maker 2', 'A side-scrolling Mario adventure that unleashes the creative potential of Super Mario Maker 2 awaits in Story Mode, which contains over 100 built-in courses. And in Course Maker, a wide range of parts, tools, and more are available so you can construct your own courses. Want coin-shooting cannons? Bowser riding on a giant Goomba? Cat Mario sliding down slopes to take out an army of baddies? Go for it! You call the shots. Pass a Joy-Con controller to a partner to build co-operatively on a single system!' FROM games WHERE igdb_id = 115276 ON CONFLICT (game_id, language_code) DO NOTHING;
