INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Just Ride', 'Just Ride is a racing game with RPG elements. Irritated cars, lucrative heists, fierce chase, wild getaways, you can do whatever you like, but please pay attention to safety. As you become immersed in the storyline, be on the lookout for vehicle upgrades, special equipment, hidden plots, and Easter eggs. Don’t be afraid to break the speed limit. Let’s Just Ride.' FROM games WHERE igdb_id = 105260 ON CONFLICT (game_id, language_code) DO NOTHING;
