INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'nStations', 'If you think this is just another simulation game about a post-apocalyptic event where people now need to colonize outer worlds... You''re SOOOO wrong. This game is the first of this genre where you can start playing in any supported platform and keep playing on others and come back anytime you want. HD graphics and outstanding sound effects and simulation features playable anywhere.' FROM games WHERE igdb_id = 127115 ON CONFLICT (game_id, language_code) DO NOTHING;
