INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'ReadySet Heroes', 'Go from zero to hero in this fast-paced multiplayer dungeon crawler meets arena brawl! Choose your character, then race through a random dungeon to slay monsters, dodge traps and collect tons of loot to power-up. You''ll need it as there''s an opposing team racing through the same dungeon! Whomever reaches the end of dungeon first will trigger a vicious "winner-take-all" arena brawl. Two teams enter, one team is left standing.' FROM games WHERE igdb_id = 116586 ON CONFLICT (game_id, language_code) DO NOTHING;
