INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Unruly Heroes', 'Unruly Heroes is a 2D action-packed adventure game inspired by the famous chinese novel ‘A journey to the west’ better known as the Monkey King Legend. Through acrobatic challenges, players take control of four unlikely heroes and fight a diverse line-up of memorable enemies in solo or coop and be part of an epic adventure in a colorful and fantasy world! Set against lushly illustrated environments in a hand-drawn art style, the game updates that classic tale to make for an epic adventure that is more colorful and lighthearted than the original, while still highlighting the essence of what it takes to be a hero. In addition to this madcap adventure, players will be able to show their kung fu style by fighting their friends in local or online PvP.' FROM games WHERE igdb_id = 37026 ON CONFLICT (game_id, language_code) DO NOTHING;
