INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kill la Kill: If', 'You control Satsuki Kiryuin as the main protagonist of this game and proceed along with the story while battling against various characters. All scenarios are completely new and fully supervised under the watchful eyes of the original scenario-writer, Kazuki Nakashima. You will be experiencing the story unfold from the perspective of Satsuki Kiryuin, the rival of the original series'' protagonist Ryuko.' FROM games WHERE igdb_id = 103369 ON CONFLICT (game_id, language_code) DO NOTHING;
