INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Asterix & Obelix XXL 3: The Crystal Menhir', 'Asterix & Obelix XXL 3: The Crystal Menhir is an action platformer and the only game in the XXL series which offers cooperative gameplay. Platforming is very different to the previous games in the series: the player can no longer jump vertically and should be more careful when moving around. The Crystal Menhir is used to clear obstacles from paths and interact with mechanisms.' FROM games WHERE igdb_id = 105002 ON CONFLICT (game_id, language_code) DO NOTHING;
