INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yakuza 5 Remastered', 'Experience the fifth chapter of the Kazuma Kiryu saga in 1080p and 60fps. Get ready for a Yakuza experience of unprecedented scale. Follow five characters across five Japanese cities, each trying to achieve their dream. The connections between them bring them together, but the conflict that unfolds is nothing any of them could have predicted.' FROM games WHERE igdb_id = 103017 ON CONFLICT (game_id, language_code) DO NOTHING;
