INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hob: The Definitive Edition', 'Hob: The Definitive Edition is an artfully crafted single-player adventure which sends gamers on a mysterious, breathtaking journey through the ruins of a lost civilization, where they will encounter strange creatures and unlock satisfying puzzles hidden throughout the world. The team at Panic Button has developed a version of the game for Nintendo Switch that provides adventurers with brand new ways to unravel the mysteries of Hob. This includes added camera controls, improvements to the game’s UI, a variety of quality-of-life improvements and new features only possible on the Nintendo Switch system, including HD rumble and touch screen functionality.' FROM games WHERE igdb_id = 116681 ON CONFLICT (game_id, language_code) DO NOTHING;
