INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Overland', 'Take care of a group of travelers on a post-apocalyptic road-trip across the United States in this turn-based survival game. Fight scary creatures, rescue stranded survivors, and scavenge for supplies like fuel, first aid kits, and weapons. Decide where to go next, whether it''s upgrading this wrecked car, or rescuing that dog. Just remember, there are consequences for every action. Get ready for close calls, dramatic escapes, hard choices, arguing about whether or not that dog gets rescued, and the end of the world.' FROM games WHERE igdb_id = 16607 ON CONFLICT (game_id, language_code) DO NOTHING;
