INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Wars Jedi: Fallen Order', 'Star Wars Jedi: Fallen Order is a narratively driven, single-player game puts you in the role of a Jedi Padawan who narrowly escaped the purge of Order 66 following the events of Episode III: Revenge of the Sith. On a quest to rebuild the Jedi Order, you must pick up the pieces of your shattered past to complete your training, develop new powerful Force abilities and master the art of the iconic lightsaber - all while staying one step ahead of the Empire and its deadly Inquisitors.' FROM games WHERE igdb_id = 74701 ON CONFLICT (game_id, language_code) DO NOTHING;
