INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Splitgate', 'Splitgate is a free-to-play, fast-paced multiplayer shooter that features player-controlled portals. This sci-fi shooter takes the FPS genre to a new dimension with its portal mechanics, delivering high-flying, multi-dimensional combat. Evoking memories of the most revered shooters of the past two decades, Splitgate embraces the classic and familiar feel of close-quarters combat while adding a unique twist.' FROM games WHERE igdb_id = 114684 ON CONFLICT (game_id, language_code) DO NOTHING;
