INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tick Tock: A Tale for Two', 'You and your friend find yourselves trapped in two magical clockworlds where you have to solve puzzles to escape. Neither of you have the whole picture so the only way to get out is to communicate what you see to the other player. Play on two devices, local or remotely, all you need is a voice connection.' FROM games WHERE igdb_id = 86295 ON CONFLICT (game_id, language_code) DO NOTHING;
