INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Walking Zombie 2', 'The world after the zombie apocalypse is a grim place. You were born into it, so you will have to struggle to survive and fight against many kinds of zombies, bandits and dangerous boss monsters. You will go on important story quests and many side quests, level up your skills and perks, sell and buy equipment, and communicate with the (un)lucky survivors in our free mobile FPS/RPG.' FROM games WHERE igdb_id = 112665 ON CONFLICT (game_id, language_code) DO NOTHING;
