INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crystal Crisis', 'An all-star cast of heroes has gathered to test their mettle in this cute and chaotic new color-matching combat game for Nintendo Switch. Crystal Crisis is presented like a one-on-one fighting game, but instead of pressing buttons to kick and punch, players arrange falling gems into matching colors to clear them from the screen and inflict damage on their opponents. It’s the ultimate puzzle battle throwdown!' FROM games WHERE igdb_id = 101152 ON CONFLICT (game_id, language_code) DO NOTHING;
