INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'American Fugitive', 'Set in a sleepy American country town in the 1980s, American Fugitive invites you to play as Will Riley. You''re no angel, but you''re not a killer. Yet the cold-blooded murder of your dad is the crime they''ve locked you up for. Fuelled by grief and a burning desire for vengeance, you must break out of jail to find the real culprit. It''s payback time.' FROM games WHERE igdb_id = 115785 ON CONFLICT (game_id, language_code) DO NOTHING;
