INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tools Up!', 'Gather up to 4 players for this fun couch co-op experience for people of all skills! Renovate the apartments in the mysterious skyscraper while the tenants are away. Be sure to follow their wishes left behind on the blueprints. Tear off wallpapers, bring down walls, bust down doors, and cover the floor with vibrant carpets and panels - just be sure to do it in time and clean up after yourself!' FROM games WHERE igdb_id = 118357 ON CONFLICT (game_id, language_code) DO NOTHING;
