INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Touhou Ibunseki: Ayaria Dawn - ReCreation', 'A classical Monopoly-like game with 20+ Touhou characters and 10+ official maps. Custom level editor, double resource system (money & crystal), electric dispatching, SP required dice throwing and weather system bring you a whole different game experience. Original characters are waiting for your challenge!' FROM games WHERE igdb_id = 126924 ON CONFLICT (game_id, language_code) DO NOTHING;
