INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Darq', 'Darq tells the story of Lloyd, a boy who becomes aware of the fact that he is dreaming. To Lloyd''s misfortune, the dream quickly turns into a nightmare and all attempts to wake up end in failure. While exploring the darkest corners of his subconscious, Lloyd learns how to survive the nightmare by bending the laws of physics and manipulating the fluid fabric of the dream world.' FROM games WHERE igdb_id = 68271 ON CONFLICT (game_id, language_code) DO NOTHING;
