INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Journey For Elysium', 'Journey For Elysium is a story-driven VR game inspired by ancient mythology. Players will take on the role of an unnamed hero who has passed away, traveling on a boat in the Underworld. In order to reach Elysium and obtain redemption, the mysterious traveler must use all his wits and skills in a series of increasingly elaborate twists and challenges. Along the way, he will discover more about his past.' FROM games WHERE igdb_id = 120758 ON CONFLICT (game_id, language_code) DO NOTHING;
