INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Killer Chambers', 'Killer Chambers is an action-platformer/memory-game hybrid. You must survive in small rooms filled with traps until one turn of the hourglass. Even if you''re hit only once you die! Nothing is left to chance, every trap pattern is made to be challenging yet fun to solve. The player must arm himself with quick reflexes and good (muscle) memory.' FROM games WHERE igdb_id = 116824 ON CONFLICT (game_id, language_code) DO NOTHING;
