INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Close to the Sun', 'Close to the Sun is a story-driven horror game that takes place at the turn of the 20th century on a mysterious ship complex created by Nikola Tesla for the sake of knowledge. In this alternative version of history, his scientific breakthroughs have already had a major impact on the world. You’re a young journalist looking for your sister and, as you approach this enormous and glorious complex for the first time, you quickly realize that something there has gone horribly wrong..."' FROM games WHERE igdb_id = 55027 ON CONFLICT (game_id, language_code) DO NOTHING;
