INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bug Fables: The Everlasting Sapling', 'Bug Fables: The Everlasting Sapling is an adventure RPG following three heroes, Vi, Kabbu, and Leif, as they embark on an epic quest in Bugaria in search of treasure and immortality. The game combines flat objects with 3D physics as the player jumps and utilizes the heroes’ unique abilities to solve puzzles and stun enemies while exploring a variety of unique, colorful areas. Battles are turn-based and with timed button inputs that can enhance your abilities.' FROM games WHERE igdb_id = 119190 ON CONFLICT (game_id, language_code) DO NOTHING;
