INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Life RPG', 'Welcome home to Sun Villa! After a long summer at grandpa''s ranch, it''s time to finish school, get a job and move into your own place. Let the adventure of life begin! Super Life (RPG) is a game about constant progression. Go to work, study or hit the gym, these actions will reward you will XP, STR (strength points) and INT (intelligence points). Earn enough points to level up and you will unlock new tasks, new job opportunities and new areas of the map to explore!' FROM games WHERE igdb_id = 120398 ON CONFLICT (game_id, language_code) DO NOTHING;
