INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Need for Speed: Heat', 'Hustle by day and risk it all at night in Need for Speed Heat, a white-knuckle street racer, where the lines of the law fade as the sun starts to set. By day, Palm City hosts the Speedhunter Showdown, a sanctioned competition where you earn Bank to customize and upgrade your high-performance cars. At night, ramp up the intensity in illicit street races that build your reputation, getting you access to bigger races and better parts. But stay ready – cops are waiting and not all of them play fair.' FROM games WHERE igdb_id = 119161 ON CONFLICT (game_id, language_code) DO NOTHING;
