INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Outer Wilds', 'Outer Wilds is a critically-acclaimed and award-winning open world mystery about a solar system trapped in an endless time loop. The newest member of the space program in a small village on the planet Timber Hearth, the player navigates a space shuttle and travels across their solar system to get to the bottom of its mysteries by exploring the cosmos and gathering the knowledge hidden within each of the system''s planets, left behind by another civilization in the distant past.' FROM games WHERE igdb_id = 11737 ON CONFLICT (game_id, language_code) DO NOTHING;
