INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pokémon Masters EX', 'Pokémon Masters EX (originally named Pokémon Masters) is a free-to-play mobile game for Android and iOS developed and published by DeNA. It is based on the Pokémon media franchise. Set on the artificial island of Pasio, the game allows players to battle and recruit various prominent Pokémon Trainers from the main series games. Originally named Pokémon Masters and released in August 2019, it was renamed Pokémon Masters EX in August 2020 on the 1st anniversary of the game.' FROM games WHERE igdb_id = 144248 ON CONFLICT (game_id, language_code) DO NOTHING;
