INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Death of Erin Myers', 'Erin Myers was a cop. Now she''s dead. But how did she die? And why did she die? Find out, as you step back in time, and play through some of the most important moments of her life. Uncover her fears, her desires, and her darkest secrets. In the end, you can''t save her. But maybe, just maybe, you can understand her.' FROM games WHERE igdb_id = 111289 ON CONFLICT (game_id, language_code) DO NOTHING;
