INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Devil May Cry 5', 'Devil May Cry 5 is a brand-new entry in the legendary over-the-top action series Devil May Cry. The game features three playable characters, each with a radically different stylish combat play style as they take on the city overrun with demons. Developed with Capcom’s in-house proprietary RE engine, the series continues to achieve new heights in fidelity with graphics that utilize photorealistic character designs and stunning lighting and environmental effects.' FROM games WHERE igdb_id = 76253 ON CONFLICT (game_id, language_code) DO NOTHING;
