INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Path of Giants', 'Path of Giants is a serene adventure puzzle game where the player controls three explorers Bern, Matchi and Totch who must help each other to conquer a set of ancient trials in search of a lost treasure. Each level focuses on the main feature of having three characters, and is hinged around the fact that the player will need to use all three of the characters in order to solve the puzzles and progress. The player will be using the boosting mechanic between the characters to help boost each other up and down platforms all while interacting with a variety of environmental moving pieces.' FROM games WHERE igdb_id = 122047 ON CONFLICT (game_id, language_code) DO NOTHING;
