INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Eternity: The Last Unicorn', 'A fully featured RPG with classic game mechanics and extensive lore based on Norse mythology. As all elven unicorns were taken away and cursed by witchcraft, the elves’ sole existence became endangered. Players will encounter mesmerizing locations and fantasy characters as Aurehen, a young pure Elf, who undertakes her quest to free the last surviving Unicorn that protects Elven immortality.' FROM games WHERE igdb_id = 96217 ON CONFLICT (game_id, language_code) DO NOTHING;
