INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('wilmots-warehouse', 77494, '2019-08-28', 85, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2fe6.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar8k0.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wilmot''s Warehouse', 'Wilmot''s Warehouse is a puzzle game about keeping a warehouse running in tip-top shape. You play as Wilmot, a hard working warehouse employee tasked with pushing, sorting and stacking a variety of products. Over time more and more truckloads of these products will arrive, gradually filling up the warehouse. How you arrange them all is entirely up to you - organize by color, type, the Dewey Decimal System, or some wild format that only you understand - it''s all good! Just remember where you put everything, because when the service hatch opens, you''ll need to find the things people want quickly, in order to earn the coveted Performance Stars required for all manner of labor-saving upgrades.' FROM games WHERE igdb_id = 77494 ON CONFLICT (game_id, language_code) DO NOTHING;
