INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nintendo Labo: Toy-Con 04 - VR Kit', '“Nintendo Labo: VR Kit is another unique Nintendo Labo experience that further blends the physical and digital worlds to bring the gameplay to life,” said Doug Bowser, Nintendo of America’s Senior Vice President of Sales and Marketing. “Many of our young fans – and even some of our older ones – have yet to try virtual reality, so this is an approachable way for kids and families to get introduced to this new world.”' FROM games WHERE igdb_id = 115875 ON CONFLICT (game_id, language_code) DO NOTHING;
