INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rise of the Teenage Mutant Ninja Turtles: Bumper Bros', 'Get some turtle wax on your shell and help Raph, Mikey, Leo, and Donnie spin, bounce, and bump off origami foot ninjas that''re lurking around the streets of NYC. In Nickelodeon''s newest free and fun action game, collect coins and pizza to unlock levels and earn trophies completing all the missions.' FROM games WHERE igdb_id = 146287 ON CONFLICT (game_id, language_code) DO NOTHING;
