INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fallout Shelter Online', 'Only available in Indonesia, Malaysia, Philippines, Thailand, Singapore, South Korea, and Japan. Fallout Shelter Online is the official successor to Fallout Shelter. Alongside the classic Vault management feature, in Fallout Shelter Online, players are also able to recruit famous heroes from the Fallout series, build perfect adventure teams, face dangerous foes, and venture into the wild Wasteland! Whomever survives the Wasteland, rules the Wasteland. Overseer, do you have what it takes to build a better future for tomorrow''s post-apocalyptic world? Prepare for a new adventure, beyond the Vault!' FROM games WHERE igdb_id = 131851 ON CONFLICT (game_id, language_code) DO NOTHING;
