INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crossniq+', 'Crossniq+ is a speed-focused, arcade-style puzzle game inspired by "y2k-era" visual design - a tribute to highly polished, small-scope Japanese games from the late 90''s. In Crossniq+, the name of the game is re-arranging a grid of tiles to form "crosses" - rows and column of the same color. You can move tiles up, down, left or right - but moving them off the edge of the grid makes them wrap back to the other side, offering a unique and brain-bending challenge. Make crosses quickly and set up multi-crosses to earn bonuses.' FROM games WHERE igdb_id = 109932 ON CONFLICT (game_id, language_code) DO NOTHING;
