INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pokémon This Gym of Mine', '"Pokemon Gym of Mine" is a fan-made game developed using the RPG Maker XP software. In the game, the player assumes the role of a custom gym leader instead of a Pokemon trainer. Players create and customize their own gyms and challenge other players to battle against them. The game features unique elements such as gym and leader customization, an original soundtrack, and an engaging story with interesting characters.' FROM games WHERE igdb_id = 227653 ON CONFLICT (game_id, language_code) DO NOTHING;
