INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lovely Planet 2: April Skies', 'Sequel to the most adorable First Person Shooter Gun Ballet. Feel the speed once again as you jump and shoot your way through the familiar cutesy abstract world filled with clever traps and angry baddies fuming with rage. Pick out targets with precision accuracy and dodge an infinite barrage of bullets carefully jumping between floating islands all while racing the clock for a better score.' FROM games WHERE igdb_id = 119351 ON CONFLICT (game_id, language_code) DO NOTHING;
