INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Classic Sudoku', 'Classic Sudoku is a sudoku puzzle game. The sudokus in the game cover a wide range of difficulty with something for everyone - and also require an incredible range of techniques to solve them efficiently! Players start with zero stars and earn stars by solving puzzles. The more puzzles you solve, the more stars you earn and the more puzzles you get to play.' FROM games WHERE igdb_id = 126741 ON CONFLICT (game_id, language_code) DO NOTHING;
